def solve():
    gross = Q(80)
    intang = Q(22)
    dta = Q(29)
    rwa = Q(1600)
    lev = Q(2600)
    pct = Q("0.14")
    base = gross - intang
    ded0 = max(dta - pct * base, Q(0))
    net0 = base - ded0

    def net(X):
        b = base + X
        d = max(dta - pct * b, Q(0))
        return b - d

    def req_rwa(X):
        return Q("0.075") * (rwa + Q("0.2") * X)

    def req_lev(X):
        return Q("0.03") * (lev + X)

    def minX(a, b):
        # need net(X) >= a + b X, a, b constants
        if net0 >= a:
            return Q(0)
        # case 1: deduction positive: net = (1+pct)*(base+X) - dta
        X1 = (a + dta - (1 + pct) * base) / ((1 + pct) - b)
        if dta - pct * (base + X1) >= 0:
            return max(X1, Q(0))
        # case 2: net = base + X
        X2 = (a - base) / (1 - b)
        return max(X2, Q(0))

    Xr = minX(Q("0.075") * rwa, Q("0.075") * Q("0.2"))
    Xl = minX(Q("0.03") * lev, Q("0.03"))
    X = max(Xr, Xl)
    if X == 0:
        bc = "none"
    elif Xr >= Xl:
        bc = "rwa"
    else:
        bc = "leverage"
    return {
        "final": X,
        "initial_net_equity_usd_million": net0,
        "initial_dta_deduction_usd_million": ded0,
        "binding_constraint": bc,
    }
